17	
18	void lv_draw_epic_fill(lv_draw_unit_t *draw_unit, const lv_draw_fill_dsc_t *dsc,
19	                       const lv_area_t *coords)
20	{
21	    if (dsc->opa <= (lv_opa_t)LV_OPA_MIN)
22	        return;
23	
24	    /* Get the clip area from the draw unit */
25	    const lv_area_t *clip_area = draw_unit->clip_area;
26	    lv_area_t clipped;
27	    if (!_lv_area_intersect(&clipped, coords, clip_area))
28	        return;
29	
30	    /* Get the target layer info */
31	    lv_layer_t *layer = draw_unit->target_layer;
32	    if (layer == NULL || layer->draw_buf == NULL || layer->draw_buf->data == NULL)
33	    {
34	        /* No buffer -- fall back to SW */
35	        lv_draw_sw_fill(draw_unit, dsc, coords);
36	        return;
37	    }
38	
39	    uint8_t *buf = layer->draw_buf->data;
40	    uint32_t buf_w = layer->draw_buf->header.w;
41	    lv_color_format_t cf = layer->draw_buf->header.cf;
42	
43	    /* Check supported color formats */
44	    uint32_t epic_cf;
45	    switch (cf)
46	    {
47	    case LV_COLOR_FORMAT_RGB565:
48	        epic_cf = EPIC_INPUT_RGB565;
49	        break;
50	    case LV_COLOR_FORMAT_RGB888:
51	        epic_cf = EPIC_INPUT_RGB888;
52	        break;
53	    case LV_COLOR_FORMAT_ARGB8888:
54	    case LV_COLOR_FORMAT_XRGB8888:
55	        epic_cf = EPIC_INPUT_ARGB8888;
56	        break;
57	    default:
58	        /* Unsupported color format -- fall back to SW */
59	        lv_draw_sw_fill(draw_unit, dsc, coords);
60	        return;
61	    }
62	
63	    /* Convert color to ARGB8888 */
64	    lv_color32_t c32 = lv_color_to_32(dsc->color, LV_OPA_COVER);
65	    uint32_t argb8888 = ((uint32_t)dsc->opa << 24) |
66	                        ((uint32_t)c32.red << 16) |
67	                        ((uint32_t)c32.green << 8) |
68	                        ((uint32_t)c32.blue);
69	
70	    /* Prepare EPIC area descriptors */
71	    EPIC_AreaTypeDef dst_area;
72	    EPIC_AreaTypeDef fill_area;
73	
74	    dst_area.x0 = 0;
75	    dst_area.y0 = 0;
76	    dst_area.x1 = (int16_t)(buf_w - 1);
77	    dst_area.y1 = (int16_t)(layer->draw_buf->header.h - 1);
78	
79	    fill_area.x0 = (int16_t)clipped.x1;
80	    fill_area.y0 = (int16_t)clipped.y1;
81	    fill_area.x1 = (int16_t)clipped.x2;
82	    fill_area.y1 = (int16_t)clipped.y2;
83	
84	    /* Call EPIC fill */
85	    int ret = drv_epic_fill(epic_cf, buf,
86	                            &dst_area, &fill_area,
87	                            argb8888,
88	                            0, NULL, NULL,  /* no mask */
89	                            NULL);          /* no callback (sync) */
90	
91	    if (ret != 0)
92	    {
93	        /* EPIC failed -- fall back to SW */
94	        lv_draw_sw_fill(draw_unit, dsc, coords);
95	    }
96	}
